"explanation": "水俣条約（Minamata Convention on Mercury）は水銀による人の健康と環境への悪影響を防止するため、水銀の採掘・使用・排出・廃棄に関する包括的な規制を定めた条約。2013年にUNEP主催の外交会議（熊本・水俣）で採択、2017年発効。日本の水俣病の経験を踏まえ「水俣」の地名が冠された。\n\nB：PCBの廃絶はストックホルム条約（POPs条約、2001年採択）が対象。水俣条約はPCBではなく水銀を規制する。\nC：日本は2016年に水俣条約を批准している（発効より早期に批准）。\nD：ストックホルム条約はPOPs（残留性有機汚染物質：DDT・PCB・ダイオキシン類等）を対象とする別の条約。\n\n【頻出】水俣条約（2013年採択・水銀規制）とストックホルム条約（2001年採択・POPs規制）の区別は頻出。\n【混同注意】バーゼル条約（有害廃棄物の越境移動規制）・ロッテルダム条約（有害化学物質の事前同意手続き）・ストックホルム条約（POPs廃絶）・水俣条約（水銀規制）の4条約の違いを整理すること。"
