"explanation": "環境基本計画は環境基本法第15条に基づき、政府（閣議決定）が策定する環境保全に関する総合的・長期的な施策の大綱。1994年に第一次が策定され、順次改定されており、第六次環境基本計画が2024年に策定された。環境省が原案を作成し閣議決定される。\n\nB：国の環境基本計画は存在する。都道府県・市町村も環境基本計画を策定できる（努力義務）が、国の計画が上位に位置する。\nC：更新は「必要に応じて」行うものであり、5年ごとに法定されているわけではない。第三次ではなく現在は第六次が最新。\nD：環境基本計画の策定は環境省が主導し、閣議決定される。経済産業省が主導するものではない。\n\n【頻出】環境基本計画の根拠法（環境基本法第15条）・策定主体（政府・閣議決定）は頻出。\n【混同注意】環境基本計画（国全体の環境政策の大綱）と地球温暖化対策計画（温暖化対策に特化）は別の計画として存在する点に注意。"
