"answer": 0,
"explanation": "温対法（1998年制定、以降改正）では、特定排出者（一定規模以上の温室効果ガス排出量を持つ事業者）に対し、毎年度の排出量を算定し国に報告することを義務付けており、報告内容は公表される（算定・報告・公表制度）。\n\nB：個人・家庭には算定・報告義務はない。対象は事業活動に伴い一定量以上の排出がある「特定排出者」（事業者）に限定される。\nC：温対法に基づくETSは一部地域・任意参加型のものが存在するが、全国義務化されているわけではない（東京都等の独自制度は都条例に基づく）。\nD：温対法は地方公共団体実行計画（自治体の温暖化対策計画）の策定義務（都道府県・大規模市）も規定している。\n\n【頻出】算定・報告・公表制度（特定排出者）の対象・手続きは頻出。地方公共団体実行計画の策定義務も重要。\n【混同注意】温対法に基づく任意参加の排出量取引と、東京都独自のキャップ・アンド・トレード制度（東京都条例）は別物として区別すること。"
