"answer": 1,
"explanation": "ISO14001は環境マネジメントシステム（EMS）の国際規格（ISO発行）であり、組織の環境パフォーマンス改善のためのPDCA（計画・実施・確認・改善）サイクルに基づくマネジメントの枠組みを規定する。認証は第三者機関による審査で取得するが、法的義務ではなく任意。\n\nA：認証取得は法的義務ではなく、任意取得。ただし取引先・入札要件等で実質的に求められる場合もある。\nC：ISO14001はマネジメントシステムの規格であり、製品の環境性能基準を定めるものではない。製品の環境性能は別のエコラベル・規格（エコマーク等）が対象。\nD：ISO14001認証取得は法令遵守を前提とするが、環境法規制の遵守義務が免除されるわけではない。行政検査の対象からも外れない。\n\n【頻出】ISO14001は「マネジメントシステムの規格」であり「製品規格」ではない点、認証が「任意」である点は頻出。\n【混同注意】ISO9001（品質マネジメント）とISO14001（環境マネジメント）の区別も問われる。"
