"explanation": "グリーン購入法（2001年施行）は国・独立行政法人等の「特定調達義務機関」に対し、環境負荷低減に資する物品・役務（環境物品等）を優先的に調達することを義務付け、毎年度の調達方針の策定・公表と調達実績の報告を求めている。\n\nA：消費者個人への義務付けはない。消費者・事業者には「努力義務」として環境物品等の選択に努めることが求められる。\nC：地方公共団体は「努力義務」とされており、国・独立行政法人等のような「義務」とは区別される。\nD：民間企業への義務付けはない。民間企業は努力義務。\n\n【頻出】国・独立行政法人等＝「義務」、地方公共団体・民間＝「努力義務」という区分は頻出ポイント。\n【混同注意】グリーン購入法（公共機関の調達義務）とグリーン購入ネットワーク（民間自主組織）は別物として区別すること。"
