"answer": 1,
"explanation": "環境配慮促進法（2005年施行）は、国・独立行政法人等の特定事業者に対して環境報告書の作成・公表を義務付けている。民間企業への作成義務は規定されていないが、一定規模の企業には努力義務が設けられている。\n\nA：すべての株式会社への義務付けはない。義務対象は国・独立行政法人等に限定される。\nC：ESG投資は非財務情報を投資判断に組み込む手法だが、高いリターンが「保証される」とは言えない。長期的なリスク管理効果が期待されるが、保証はない。\nD：GRIスタンダードは民間のNGO（GRI：Global Reporting Initiative）が策定した自主的なサステナビリティ報告のガイドラインであり、法的拘束力はない。\n\n【頻出】環境配慮促進法の義務対象（特定事業者）と民間企業の位置付け（努力義務）の違いは頻出。\n【混同注意】GRIスタンダード・TCFD・TNFD等の非財務報告フレームワークはいずれも民間主導の任意基準であり、法的義務ではない点を整理すること。"
