"explanation": "省エネ法（1979年制定、以降改正）では、エネルギー使用量が一定規模以上の工場・事業場を「特定事業者」として指定し、エネルギー管理者（または管理員）の選任、毎年度の定期報告書・中長期計画書の国への提出を義務付けている。2022年改正で非化石エネルギーへの転換促進も目的に追加。\n\nA：省エネ法は工場・事業場・輸送・建築物・機械器具等の幅広い分野を対象とする。家庭のみではない。\nC：トップランナー制度は「市場に出回る最も優れた（省エネ性能が高い）製品」を基準とし、一定期間後に全製品がその水準を達成するよう義務付けるもの。最低基準（ボトムアップ）ではなく最高水準（トップランナー）が基準。\nD：2022年改正は非化石エネルギーへの「転換促進」が趣旨であり、化石エネルギー使用増加を推進する内容ではない。\n\n【頻出】トップランナー制度の仕組み（最高性能品を目標基準とする）は頻出。特定事業者への報告義務も重要。\n【混同注意】省エネ法の特定事業者（エネルギー使用量基準）と温対法の特定排出者（CO₂排出量基準）は別制度。"
