"FIT制度は再生可能エネルギーで発電した電気を、国が定めた価格で一定期間電力会社が買い取ることを義務付ける制度であり、費用は再エネ賦課金として電気料金に上乗せされる",
"FIT制度は再生可能エネルギーの導入を促進するため、発電設備の初期投資費用を国が全額補助する補助金制度である",
