"地下水の過剰採取は地盤沈下や塩水浸入の原因となるが、採取量を減らせば短期間で元の水位に回復する",
"仮想水（バーチャルウォーター）の概念により、水不足地域からの農産物輸入は実質的に水資源を輸入していることと等しいと考えられる"
