"answer": 2,
"explanation": "地下水は長年かけて涵養（補充）されたものであり、過剰採取による枯渇や水位低下からの回復には数十年〜数百年を要する場合がある。「短期間で回復する」は誤りであり、地下水の持続可能な管理が重要とされる所以である。\n\nA：正しい。淡水2.5%のうち約69%が氷河・氷床、約30%が地下水として存在し、河川・湖沼等として直接利用できるのはごく一部。\nB：正しい。水ストレス（年間利用可能水量の40%以上を使用）は中東・北アフリカ・南アジアで深刻であり、気候変動による悪化も予測される。\nD：正しい。バーチャルウォーターの観点から、食料輸入は水不足国が不足する水を節約する効果があるとも言える。\n\n【頻出】淡水の存在割合（2.5%、かつそのほとんどが氷河・地下水）は基本数値として頻出。\n【混同注意】地下水は再生可能だが涵養速度が非常に遅い。「使い捨て」に近い地下水（化石水）も存在する点に注意。"
