"explanation": "サーキュラーエコノミー（CE）は「採掘→製造→使用→廃棄」というリニアエコノミー（線形経済）に対して、廃棄物・汚染をなくし、製品・素材を循環させ続け、自然を再生するという3原則を持つ経済システム。設計段階から廃棄物ゼロを想定し、長寿命化・修理・再利用・再製造・リサイクルの優先順位で資源を活用する。\n\nA：これはリニアエコノミー（線形経済）の説明であり、サーキュラーエコノミーの対極にある。\nC：サーキュラーエコノミーはリサイクルだけでなく、修理・修復・再利用・再製造・アップサイクル等を含む広い概念。リサイクルはむしろ最後の手段として位置付けられる。\nD：EUは2015年にサーキュラーエコノミー行動計画を採択し、世界的な推進の中心となっている。日本発の概念ではない。\n\n【頻出】リニアエコノミー（大量生産・大量廃棄）とサーキュラーエコノミー（資源循環）の対比は頻出。\n【混同注意】3Rと循環経済は重なる部分があるが、CEはより上流の設計段階から廃棄物をなくすという概念まで含む点で広い。"
