"explanation": "熱帯林の減少は東南アジア（インドネシア・マレーシア・ミャンマー等）・中南米（アマゾン流域：ブラジル等）・アフリカ（コンゴ盆地等）の3地域いずれでも深刻であり、特にブラジルやインドネシアでの大規模な森林減少が報告されている。アフリカのみというのは明確な誤り。\n\nA：正しい。森林はCO₂吸収源・生物多様性ホットスポット・水源地として機能し、その減少は複合的な影響を持つ。\nB：正しい。大豆・パーム油等のプランテーション開発や牧草地化が近年の熱帯林減少の主要因となっている。\nC：正しい。REDD＋（Reducing Emissions from Deforestation and forest Degradation）は気候変動対策の枠組みの中で途上国の森林保全を支援する仕組み。\n\n【頻出】熱帯林減少の3大地域（東南アジア・中南米・アフリカ）とREDD＋の仕組みは頻出。\n【混同注意】REDD＋は「森林を守ることで排出削減クレジットを得る」仕組みであり、単純な補助金制度とは異なる点に注意。"
