"answer": 1,
"explanation": "ESGはEnvironment（環境）・Social（社会）・Governance（ガバナンス＝企業統治）の頭文字。財務情報だけでなくこれらの非財務情報を投資判断に組み込むことで、中長期的なリスク管理と持続可能な価値創造を目指す投資手法。国連責任投資原則（UNPRI）の採択（2006年）以降、機関投資家・年金基金を中心に急拡大した。\n\nA：GはGovernmentではなくGovernance（企業統治）。ESGは非財務情報を「加味」する手法であり財務情報のみではない。\nC：ESG投資の主体は機関投資家・年金基金・運用会社であり、むしろこれらが中心的推進者。NGO・NPOに限定されない。\nD：E・S・Gの3要素はいずれもESGの構成要素であり、省略可能な任意項目という規定はない。\n\n【頻出】ESGの正確な展開（Environment・Social・Governance）と、非財務情報を投資に組み込む手法という定義は頻出。\n【混同注意】ESG投資（投資家の視点）とCSR（企業の社会的責任、企業の視点）は異なるが相互に関連する概念。"
