"answer": 1,
"explanation": "地域循環共生圏は第五次環境基本計画（2018年）で提唱された概念。都市・農村・中山間地域等それぞれの特性を生かした自立・分散型の地域社会を形成しながら、地域間が連携・補完し合うことで、国全体として資源・エネルギー・人材の循環を実現するビジョン。\n\nA：他地域との移動を「禁止」するのではなく、地域間の補完・連携を積極的に位置付けている点が重要。\nC：農山漁村・離島・中山間地域こそが自然資本・再生可能エネルギーの供給拠点として積極的に対象とされている。\nD：地域循環共生圏は第五次環境基本計画（2018年）が初出。第三次（2006年）ではない。\n\n【頻出】地域循環共生圏＝第五次環境基本計画・自立分散＋地域間連携という概念は頻出。\n【混同注意】地域循環共生圏は「地域完結型」ではなく「地域間補完型」であることが最重要ポイント。"
