"explanation": "再生可能エネルギー特別措置法は2011年に成立・2012年7月施行。太陽光・風力・水力・地熱・バイオマス発電の電力をFIT制度によって固定価格で電力会社に買い取らせることを定め、特に太陽光発電の導入量が急拡大した。\n\nB：日本の地熱発電は資源量は豊富とされているが、国立公園内での開発規制・住民の反対等から導入が進まず、発電量全体に占める割合は数%程度にとどまる。50%以上は明らかに誤り。\nC：FITの買取価格は電源種別（太陽光・風力・地熱・バイオマス等）・規模（出力kW数）によって異なる価格が設定されており、一律ではない。\nD：再エネ特措法は文字通り再生可能エネルギーのみを対象とし、石炭火力には適用されない。\n\n【頻出】再エネ特措法の施行年（2012年）とFIT制度の概要は頻出。電源種・規模別に異なる買取価格も重要。\n【混同注意】FIT（2012年〜）とFIP（2022年〜）の違い、およびFITの課題（賦課金の増大・太陽光偏重）も整理しておくこと。"
