"explanation": "四大公害病は①水俣病（熊本：有機水銀/チッソ）②新潟水俣病（新潟：有機水銀/昭和電工）③イタイイタイ病（富山：カドミウム/三井金属）④四日市ぜんそく（三重：亜硫酸ガス等/石油化学コンビナート）。水俣病は有機水銀（メチル水銀）による神経障害、イタイイタイ病はカドミウムによる骨軟化症・腎障害が特徴。\n\nA：四大公害病にはメチル水銀・カドミウム等水質・土壌汚染が原因のものが含まれており、大気汚染のみではない。\nC：四日市ぜんそくは亜硫酸ガス（SO₂）等が原因であり、NOₓは主因ではない。新潟水俣病は有機水銀が原因。\nD：四大公害訴訟はいずれも原告側（被害者）が勝訴し、企業の不法行為責任が認められた。この判決群が公害対策法整備を加速させた。\n\n【頻出】四大公害病の地域・原因物質・加害企業の対応はセットで頻出の暗記事項。\n【混同注意】水俣病（有機水銀）とイタイイタイ病（カドミウム）の原因物質を入れ替えた誤答は最多ミスパターン。"
