"explanation": "ヒートアイランド現象は都市部でアスファルト・コンクリートによる蓄熱・緑地減少・エアコン等の人工排熱の増加等により、郊外・農村部より都市中心部の気温が高くなる現象。夏季の熱中症リスク増大・集中豪雨の頻度増加・冷房需要増大によるさらなる熱排出の悪循環等の影響がある。\n\nB：ヒートアイランドは都市スケールの気温上昇であり、地球温暖化（全球規模）とは発生メカニズムが異なる。CO₂削減だけでなく緑化・高反射率舗装・排熱抑制等の対策が必要。\nC：ヒートアイランドは夏季に特に顕著であり、熱中症増加の要因となる。冬季にも観測されるが夏季の影響が大きい。\nD：オゾン層破壊は紫外線増加の原因であり、ヒートアイランド現象の主因ではない。\n\n【頻出】ヒートアイランドの原因（人工排熱・蓄熱・緑地減少）と対策（屋上緑化・透水性舗装・緑化）は頻出。\n【混同注意】ヒートアイランド（都市スケール）と地球温暖化（全球スケール）は異なる現象。両方が重なって都市の高温化が進む点には注意。"
