"explanation": "土壌汚染対策法（2002年制定）では、①有害物質使用特定施設の廃止時、②土地の形質変更（3000㎡以上）の届出時、③健康被害のおそれがある場合に都道府県知事が調査を命令できる。汚染が確認された区域は「要措置区域」または「形質変更時要届出区域」として指定・公示され、必要な対策が求められる。\n\nA：農地に加え、工場跡地・市街地の土壌汚染も対象。農用地土壌汚染防止法と混同しないこと。\nC：汚染原因者が特定できる場合は原因者に費用負担・措置命令。国費で全額実施するわけではない。\nD：規制対象には重金属（鉛・砒素・カドミウム等）だけでなく、VOC（トリクロロエチレン・テトラクロロエチレン等）、農薬、シアン化合物等の特定有害物質25物質（改正時点）が含まれる。\n\n【頻出】調査義務が生じるトリガー（施設廃止・土地形質変更等）と指定区域の種類（要措置・形質変更時要届出）は頻出。\n【混同注意】土壌汚染対策法（市街地等）と農用地土壌汚染防止法（農地）は対象地域が異なる別の法律。"
