"answer": 0,
"explanation": "気候変動対策は「緩和（Mitigation）」と「適応（Adaptation）」の2本柱。緩和：再エネ普及・省エネ・森林保全等によるGHG排出削減や吸収強化（原因への対処）。適応：気温上昇・海面上昇・異常気象等の影響を前提に、農業品種改良・洪水対策・熱中症予防等の被害最小化策（結果への対処）。両者は補完的であり、どちらか一方のみでは不十分。\n\nB：緩和と適応は全く異なる概念。緩和は原因（GHG）への対処、適応は影響への対処。\nC：適応策は緩和で防げなかった影響への備えであり、緩和そのものの代替にはならない。両者を並行して進めることが重要。\nD：日本では温対法（緩和）と気候変動適応法（2018年施行、適応）の両方が制定されている。\n\n【頻出】緩和（原因対処・排出削減）と適応（影響対処・被害軽減）の定義の違いは最頻出テーマの一つ。\n【混同注意】「適応」策は温暖化を防ぐのではなく「被害を減らす」ものであり、温暖化阻止効果はない点に注意。"
