"answer": 0,
"explanation": "越境汚染（Transboundary Pollution）は大気・水・土壌等を通じて汚染物質が国境を越えて拡散する現象。酸性雨（SO₂・NOₓの長距離輸送）・黄砂・PM2.5・POPs・海洋プラスチック・気候変動（GHG）等が代表例。国境を越えるため一国の対策のみでは解決できず、国際条約・二国間協定・多国間協力が必要。\n\nB：越境汚染は風・海流・河川等を通じて複数国・大陸をまたぐ広域問題（例：チェルノブイリ事故の放射性物質の欧州拡散）も発生する。\nC：汚染者責任原則（PPP）と国際環境法では発生国の責任が問われるが、実際の費用負担・解決は国際交渉・条約に基づく協力で対応する。被害国が費用を全く負担しないというわけではない。\nD：PM2.5は粒径2.5μm（マイクロメートル）以下の微小粒子状物質。自動車排ガス・工場・火力発電等の人為的発生源と、自然発生源（海塩粒子・土壌粒子）の両方を含む。\n\n【頻出】PM2.5の正確な定義（2.5μm以下）と越境大気汚染の問題は頻出。\n【混同注意】PM2.5（2.5μm以下の微小粒子）とSPM（浮遊粒子状物質、10μm以下）は基準粒径が異なる別の環境基準。"
