"answer": 1,
"explanation": "気候正義（Climate Justice）は、温室効果ガスの排出に最も貢献してきた先進国・富裕層が多くの責任を負う一方、最も影響を受けやすいのは排出量が少ない途上国・小島嶼国・貧困層・将来世代であるという不公平を指摘する概念。パリ協定の「共通だが差異ある責任（CBDR）」原則や、損失と損害（Loss & Damage）の議論にも反映されている。\n\nA：気候正義は不公平を「正当化」するのではなく、「問い直し、是正」する概念。\nC：共通だが差異ある責任（CBDR）原則は先進国と途上国の歴史的責任・能力の違いを踏まえた差異化を認めており、一律同一義務は気候正義の立場から問題とされる。\nD：気候正義の概念は1990年代から議論されており、2020年以降の新概念ではない。\n\n【頻出】気候正義と「共通だが差異ある責任（CBDR）」原則・損失と損害（Loss & Damage）の関係は頻出テーマ。\n【混同注意】CBDR（共通だが差異ある責任）はリオ宣言（1992年）に由来する原則であり、パリ協定にも引き継がれている。"
