"explanation": "CCS（Carbon Capture and Storage）は発電所・工場等の排出源でCO₂を回収・圧縮し地中の地層・帯水層に圧入・貯留する技術。CCUS（利用も含む）と呼ぶ場合もある。DAC（Direct Air Capture）は大気中のCO₂を直接回収する技術で、既存排出量の削減（CDR：炭素除去）として期待されるが、現状は非常に高コスト・高エネルギー消費。\n\nB：CCSの世界的な展開規模は現在の排出量（年間約370億t）に対し極めて小規模にとどまり、問題解決済みとは言えない。\nC：DACは現状で1tCO₂あたり数百〜1,000ドル以上のコストと大量のエネルギーを要するため、大規模展開の課題が大きい。\nD：適切な地層・帯水層に貯留されたCO₂は数千年単位で安定して封じ込められると評価されており、短期間での自然分解は誤り。\n\n【頻出】CCS（排出源回収・地中貯留）とDAC（大気直接回収）の違いと、現状の課題（コスト・規模）は頻出。\n【混同注意】BECCS（バイオエネルギー＋CCS）はバイオマスの燃焼で生じるCO₂を回収・貯留することで「ネガティブエミッション」を実現する概念であり、CCSとDACとは区別すること。"
