"explanation": "水循環は気候変動（気温上昇・降水パターン変化）・森林破壊・都市化（不透水面増加）・地下水過剰採取等の人間活動によって大きく変化していることが確認されている。干ばつの頻発化・洪水の激化・地下水位低下等はその証拠。「一定周期で変化なし」は誤り。\n\nA：正しい。太陽エネルギーが駆動力となり、蒸発→大気輸送→降水→地表流出・浸透→蒸発という水循環が成立している。\nB：正しい。温暖化による蒸発散増加→大気中水蒸気増加→降水量・強度の変化（湿潤地域はより湿潤に、乾燥地域はより乾燥に）という傾向が予測・観測されている。\nC：正しい。森林の保水・蒸散機能は地域の水循環・降水量維持に貢献しており、アマゾン等の大規模森林破壊が地域降水量の減少につながるとの研究がある。\n\n【頻出】水循環と気候変動・森林の関係は地球環境の複合的問題として頻出。\n【混同注意】「水循環の加速」は必ずしも水供給の増加を意味せず、極端気象（豪雨・干ばつ）の頻発化として現れる点に注意。"
