"explanation": "環境倫理学の主な立場：①人間中心主義（Anthropocentrism）：人間の利益・福祉が価値の基準、自然は手段的価値。②動物中心主義（Zoocentrism）：感覚ある動物に固有の価値を認める（シンガー・レーガン等）。③生命中心主義（Biocentrism）：すべての生命に固有の価値。④生態中心主義（Ecocentrism）：生態系・自然全体に内在的価値を認める（アルド・レオポルド等）。\n\nB：生態中心主義は人間以外の自然・生態系にも固有（内在的）価値を認める立場であり、人間中心主義とは逆。\nC：将来世代への責任はブルントラント定義・持続可能な開発の中核概念であり、現代の環境倫理の主要テーマ。\nD：深い生態学（ディープエコロジー、アルネ・ネス提唱）は人間中心主義を批判し、自然の固有価値・人間と自然の平等性を強調する立場。浅い環境主義（Shallow Ecology）は人間中心主義的アプローチであり、深い生態学とは対照的。\n\n【頻出】人間中心主義・生態中心主義の対比と、深い生態学（ディープエコロジー）の特徴は頻出。\n【混同注意】ディープエコロジー（人間と自然の平等・自然の固有価値）とシャローエコロジー（人間中心・環境は人間のために保護）の違いは確実に区別すること。"
