"answer": 0,
"explanation": "炭素税：政府がCO₂等の排出に対して単位あたり固定の税率を設定（価格を固定、削減量は企業の判断で変動）。ETSはキャップ・アンド・トレード：政府が排出総量の上限（キャップ）を設定し、排出枠（クレジット）を配分・取引させる仕組み（数量を固定、価格は市場で変動）。どちらも排出削減のための「カーボンプライシング」手段であり、各国が独自または組み合わせて導入している。\n\nB：炭素税とETSは異なる仕組み。炭素税は価格固定・ETSは数量固定という根本的な違いがある。\nC：説明がAとBを入れ替えており誤り。ETSが数量固定・市場価格決定、炭素税が価格固定の仕組み。\nD：国際条約による縛りはなく、炭素税・ETSとも途上国を含む各国が独自に導入できる。チリ・コロンビア等の途上国でも炭素税が導入されている。\n\n【頻出】炭素税（価格固定・数量変動）とETS（数量固定・価格変動）の根本的な違いは最頻出の比較問題。\n【混同注意】カーボンプライシングは炭素税・ETS・内部炭素価格等を包含する上位概念。それぞれの仕組みの違いを整理すること。"
