"answer": 0,
"explanation": "自然資本の経済的評価は、森林の炭素吸収・水源涵養・生物多様性維持、湿地の水質浄化・洪水調節等の生態系サービスに貨幣価値を付与することで、環境の損失が経済的コストとして「見える化」される手法。TEEB（2010年）・IPBES生態系評価・企業の自然資本会計（TNFD等）等で活用が進む。\n\nB：TEEB・世界銀行の「包括的な富」指標・企業の自然資本会計等、多くの機関・企業が取り組んでいる。\nC：国際的に禁止されているわけではなく、むしろ自然資本のGDPへの組み込み（SEEA：環境経済統合勘定）が国連主導で整備されている。\nD：TEEBは生態系サービスの経済的価値を「可視化・主流化」するためのプロジェクトであり、価値ゼロとの結論は提示していない（逆の目的）。\n\n【頻出】TEEB（生態系の経済学・価値の可視化）とTNFD（企業の自然関連情報開示）の趣旨・関係は頻出。\n【混同注意】自然資本の「貨幣価値換算」は便宜的手法であり、真の価値を完全に表せるわけではないという限界論も存在することを覚えておくこと。"
