"answer": 0,
"explanation": "Just Transition（公正な移行）は脱炭素化・エネルギー転換の過程で炭鉱・石油産業等の労働者・地域が職を失う等の不公平な負担を被らないよう、再教育・再就職支援・地域経済多様化等の社会的支援策を伴う移行を実現する考え方。ILO・COP26宣言・EUグリーンディール等に組み込まれている。\n\nB：Just Transitionは化石燃料産業の労働者・地域への補償・支援を積極的に求めるものであり、排除する考え方とは逆。\nC：欧州（EU Just Transition Fund）・米国（インフレ削減法の関連措置）・日本でもエネルギー転換地域への支援策の文脈で議論されており、先進国でも重要なテーマ。\nD：Just Transitionは産業・地域の状況に応じた段階的・公正な移行を支持するものであり、一律同時の強制とは異なる。\n\n【頻出】Just Transitionの概念（脱炭素化に伴う社会的公正・労働者支援）はパリ協定・COP26以降の頻出テーマ。\n【混同注意】Just Transition（移行の公正性）と気候正義（Climate Justice、影響の公正性）は関連するが異なる概念。"
