"answer": 0,
"explanation": "CBAM（Carbon Border Adjustment Mechanism、炭素国境調整メカニズム）はEUが2023年より移行期間を開始した制度。鉄鋼・セメント・アルミ・肥料・電力・水素等の指定品目についてEU輸入業者が当該製品の生産に伴うCO₂排出量を申告し、EU-ETSの炭素価格相当額のCBAM証書を購入する義務を負う。カーボンリーケージ（企業が規制の緩い国に生産移転すること）の防止が目的。\n\nB：CBAMはEUが輸入品に課す制度であり、WTO管理の条約でも輸出規制でもない。\nC：対象は鉄鋼・セメント・アルミ・肥料・電力・水素等の特定産業に限定されており、農産物・繊維・電子機器全品目ではない。\nD：米国・日本・カナダ等でも国境炭素調整の検討・議論が進んでいる。\n\n【頻出】CBAMの目的（カーボンリーケージ防止）・対象品目（鉄鋼・セメント・アルミ等）・EU-ETSとの関係は頻出最新テーマ。\n【混同注意】CBAM（輸入品への炭素コスト賦課）とカーボン税（国内排出への課税）・ETS（国内の排出量取引）は異なる仕組み。"
