"explanation": "インパクト投資（Impact Investing）はGIIN（Global Impact Investing Network）が定義する投資手法で、「意図的に（Intentionality）・財務的リターンと社会的・環境的成果を同時に追求し・成果を測定・管理する」ことが3要件。社会課題解決（貧困・教育・環境等）と財務収益の両立を目指す。\n\nB：ネガティブスクリーニング（問題企業・業種を投資対象から除外）はESG投資の一手法であり、インパクト投資とは異なる概念。\nC：インパクト投資は財務的リターンも要件の一つ。慈善事業（フィランソロピー）は財務リターンを求めない点で異なる。\nD：ESG投資（非財務情報の考慮・既存資産への組み込み）とインパクト投資（意図的な社会課題解決への投資）は重なる部分があるが、意図性・測定・追加性等の要件が異なる別概念。\n\n【頻出】インパクト投資の3要件（意図性・財務+社会環境リターン・測定）はGIINの定義として頻出。\n【混同注意】インパクト投資（積極的に社会・環境効果を生む投資）とネガティブスクリーニング（問題企業を除外する投資）は方向性が異なる。"
