"explanation": "バイオプラスチックは2軸で分類される。①原料：バイオマス由来（植物等）vs石油由来。②分解性：生分解性 vs非生分解性。バイオマス原料でも非生分解性のものがあり（バイオPET等）、生分解性でも石油由来のものがある（ポリカプロラクトン等）。両性質を兼ね備えるのはポリ乳酸（PLA）・PHAのみ。\n\nB：生分解性プラスチックでも海洋環境（低温・紫外線不足）では分解が非常に遅く、海洋汚染の原因になり得る。「短期間に完全分解」「影響なし」は誤り。\nC：バイオマス由来プラスチックの燃焼によるCO₂はカーボンニュートラルと見なせる（植物成長時に吸収したCO₂を再放出）が、製造・輸送エネルギー等を含めたLCA全体では必ずしも石油由来より少ないとは限らない。\nD：生分解速度は温度・水分・微生物の存在等の環境条件に大きく依存し、堆肥化設備（高温・好気性）では速く分解されるが、海洋・土壌では非常に遅い場合がある。\n\n【頻出】バイオプラスチックの2軸分類（原料・分解性）と、「バイオ=海洋で分解」という誤解の払拭は頻出。\n【混同注意】PLA（ポリ乳酸・バイオマス原料・生分解性）とバイオPET（バイオマス原料・非生分解性）は原料が同じでも分解性が異なる代表例。"
