"explanation": "ア・イ・エが正しい。ウが誤り。\n\nア：正しい。デジタルツインはスマートシティ・工場・建築等でのエネルギー最適化・環境シミュレーションに活用されている。\nイ：正しい。SAF（Sustainable Aviation Fuel）はバイオマス・廃食油・廃棄物・合成燃料等から製造され、従来ジェット燃料比でライフサイクルCO₂を最大80%以上削減できるとされる。航空分野の脱炭素で注目度が急増している。\nウ：誤り。カーボンリサイクルとは回収したCO₂を原料として燃料・化学品・コンクリート等に変換・再利用することであり、大気へのCO₂放出を抑制する技術。廃プラ→化石燃料製造という定義は誤り。\nエ：正しい。メタネーションはPower-to-Gas技術の一種で、再エネ余剰電力で水電解→水素製造→CO₂と反応→合成メタン（CH₄）製造。既存のガスインフラに流せる点が利点。\n\n【頻出】SAF（航空燃料の脱炭素）とメタネーション（Power-to-Gas）は近年の最頻出新技術テーマ。\n【混同注意】カーボンリサイクル（CO₂の資源化・再利用）とカーボンリサイクルコンクリート（CO₂をコンクリートに固定化）は関連するが区別すること。"
