"answer": 0,
"explanation": "出力制御（カーテイルメント）は太陽光・風力等の変動電源が多量に発電し電力需要を超過した際、送電線の過負荷・周波数異常を防ぐために発電量を強制的に抑制すること。九州・中国・四国電力管内等で頻発しており、余剰電力の有効活用（蓄電池・水素製造・揚水発電・需要シフト）が課題。\n\nB：出力制御は供給過多時（余剰発電）の対策であり、不足時の増発とは逆の概念。\nC：現状では出力制御時に余剰電力をすべて蓄電池に貯蔵できるインフラは整っておらず、実際に発電が抑制（無駄に）なっているケースが多い。\nD：出力制御は電力系統の安定維持のための技術的・運用上の必要措置であり、意図的な再エネ抑制のための行為ではない。\n\n【頻出】出力制御の原因（再エネ余剰）・発生地域（九州等）・対策（蓄電池・水素製造・需要シフト）は頻出。\n【混同注意】出力制御（余剰時の抑制）とデマンドレスポンス（需要側の調整）は電力系統安定化の異なるアプローチ。"
