"explanation": "昆明・モントリオール生物多様性枠組（GBF）は2022年12月のCBD COP15（カナダ・モントリオール）で採択。23の行動目標のうち最重要目標として、2030年までに陸域・内陸水域・海域・沿岸域それぞれ少なくとも30%を実効的に保護・保全する「30by30」目標を掲げる。また侵略的外来種対策・汚染削減・生物多様性に有害な補助金の廃止等も含む。\n\nB：GBFは2022年のCOP15採択。愛知目標（2010年COP10採択・2020年達成期限）の後継だが、GBFの採択年は2022年。\nC：30by30は陸域（30%）と海域（30%）の両方を対象とする。陸域のみ・海域のみでなく両方が目標。\nD：GBFは先住民族・地域コミュニティ（IPLC）の権利尊重・伝統的知識の保護・公正な利益配分を明示的に重視しており、これらへの言及がないというのは誤り。\n\n【頻出】GBF（2022年・COP15）の「30by30」目標（陸域・海域ともに30%保護）と愛知目標との関係は最重要時事テーマ。\n【混同注意】COP15（生物多様性条約の締約国会議）とCOP（気候変動枠組条約の締約国会議）は全く別の会議であることに注意。"
