"explanation": "都市緑地は孤立した緑地同士をつなぐグリーンコリドー（生態的回廊）として機能し、鳥類・昆虫・哺乳類の移動・繁殖を支援する。屋上緑化・壁面緑化・雨庭・生物多様性配慮型公園等の設計により都市の生態系ネットワークが形成できる。さらにヒートアイランド緩和・雨水浸透・住民の精神的健康（生物との接触効果）等の多機能性がある。\n\nB：都市部でもツバメ・スズメ・タヌキ・都市型ミツバチ（都市養蜂）等の生物が生息・繁殖しており、緑地整備・巣箱設置等の工夫で生物多様性を向上できる。\nC：屋上緑化は夏季の日射を吸収・遮断し室内温度上昇を抑制する効果があり、建物の冷房エネルギー削減（省エネ）に貢献することが多い。\nD：グリーンコリドーは野生動物の移動経路を確保するための生態的連続性の概念であり、道路緑化帯というより孤立した自然環境を「つなぐ」緑地ネットワークを指す。\n\n【頻出】グリーンコリドー（生態的回廊）の役割と都市緑化の多機能性（ヒートアイランド・生物多様性・健康）は頻出。\n【混同注意】グリーンコリドー（生態的回廊・生物移動路）と防風林・街路樹（植栽）は目的・機能が異なる。"
