"explanation": "Nature-based Solutions（NbS）はIUCN（国際自然保護連合）が定義した概念で、「社会課題に効果的・適応的に対処し、人間の幸福と生物多様性に恩恵をもたらす、自然および改変された生態系を保護・持続可能な管理・回復する行動」。EbA（気候適応）・Eco-DRR（防災）・グリーンインフラ・森林炭素吸収等を包含する上位概念として位置付けられる。\n\nB：NbSはバイオテクノロジーによる生物改変ではなく、既存の生態系の保全・回復・管理の活用が基本。\nC：NbSは気候変動緩和（森林吸収等）・適応（防災・水管理等）・生物多様性保全・食料・健康等の複数の社会課題に同時に対応するコベネフィット（共便益）が特徴。\nD：IPCCはNbSの中の森林保全・土地管理・農業改善等を温暖化緩和策として明示しており、否定していない。ただしNbSのみで削減目標を達成することはできないとも強調している。\n\n【頻出】NbSの定義（IUCN）・グリーンインフラ・EbA・Eco-DRRとの関係・コベネフィットの概念は頻出。\n【混同注意】NbS（上位概念）はEbA（気候適応特化）・グリーンインフラ（都市・社会インフラ文脈）・Eco-DRR（防災文脈）を包含する関係性を整理すること。"
