"answer": 0,
"explanation": "グローバルストックテイク（GST）はパリ協定第14条に基づく5年サイクルの全体評価プロセス。集団的な緩和・適応・資金提供の進捗と気候目標とのギャップを評価し、各国が次のNDC策定・引き上げの際の判断材料とする「ラチェット（引き締め）メカニズム」の中核。第1回GSTはCOP28（2023年）で完了し、現在の対策では1.5℃目標達成が困難であると結論付けた。\n\nB：GSTには個別国への制裁規定はない（パリ協定自体が強制力を持たない任意的な仕組み）。評価は集団的な進捗の確認と自主的な野心引き上げの促進を目的とする。\nC：第1回GSTはCOP28（2023年、UAE・ドバイ）で完了・公表済み。COP30は2025年（ブラジル・ベレン）予定。\nD：GSTは各国政府の交渉・合意プロセスであり、IPCCの科学的評価（AR等）を参照しながら政府間で実施される。\n\n【頻出】GSTの目的（5年ごとの全体評価→NDC引き上げへのラチェット）と第1回GST（COP28・2023年）の完了は頻出。\n【混同注意】GST（全体の集団的進捗評価）とNDC（各国の個別削減目標）・IBA（履行透明性フレームワーク、個別国の報告審査）を区別すること。"
