"explanation": "SEEA EA（System of Environmental-Economic Accounting – Ecosystem Accounting）は2021年に国連統計委員会で国際統計基準として採択。森林・湿地・農地・海洋等の生態系の面積・状態（物理的ストック）と、炭素吸収・水供給・授粉・洪水調節等の生態系サービスの供給量・経済価値（フロー）を国民経済計算（GDP等）と整合した形で計測・報告する枠組み。\n\nB：SEEA EAは企業財務会計ではなく国民勘定（マクロ統計）の枠組み。金銭的評価は一部含まれるが物理的勘定が基本であり、GDPと同一方法で義務算定するわけではない。\nC：生態系勘定は市場価格がつかない非市場的な生態系サービス（洪水調節・授粉・文化的価値等）の評価・計測も重要な対象とする。\nD：GDPの廃止を義務付けるものではなく、既存の国民勘定を「補完・拡張」する統計基準として位置付けられる。\n\n【頻出】SEEA EA（2021年国連採択・生態系勘定の国際基準）は自然資本主流化の文脈で近年急速に注目度が上がっている頻出テーマ。\n【混同注意】SEEA（環境経済統合勘定、物質フロー・エネルギー等の環境統計の枠組み）とSEEA EA（生態系勘定、2021年採択の最新部分）は同じSEEA体系の異なるモジュール。"
