"explanation": "グリーンサプライチェーンマネジメント（GSCM）は原材料調達から製造・物流・販売・使用済み品回収・リサイクルに至る全段階で環境配慮を組み込む経営手法。原材料の環境認証確認・輸送効率化によるCO₂削減・使用済み製品の回収リサイクル体制整備等が含まれる。近年はスコープ3の開示要求強化を背景に取り組みが加速している。\n\nB：調達コスト最小化とは異なり、環境負荷低減を主目的とした調達・物流管理がGSCMの本質。\nC：製造業・食品・小売等では自社の直接排出（スコープ1・2）よりサプライチェーン全体（スコープ3）の排出量が大幅に上回るケースが多く、スコープ3の削減が最大のインパクトを持つ場合が多い。\nD：グリーン調達は産地（国産・輸入）ではなく、製品の環境性能・環境認証の有無を基準に調達先・製品を選定する手法。\n\n【頻出】GSCM・グリーン調達・スコープ3削減の関連は企業環境経営の頻出テーマ。\n【混同注意】グリーン調達（環境配慮製品の優先調達）とグリーン購入法（公共機関の法的義務）は主体・仕組みが異なる。"
