"answer": 0,
"explanation": "赤道原則（Equator Principles）は2003年に策定された、大規模インフラ・産業プロジェクト融資の際に環境・社会リスクを評価・管理するための民間金融機関の自主的な枠組み。IFC（国際金融公社）のパフォーマンス基準に基づき、生物多様性・地域コミュニティ・先住民族・気候変動等の10原則に準拠した評価・監視を求める。\n\nB：赤道原則は途上国に限定されず、世界中のプロジェクトに適用される（第3版以降は全地域対象）。\nC：PRIは国連環境計画・金融イニシアチブ（UNEP FI）と国連グローバルコンパクトが2006年に策定した自主的な原則であり、中央銀行規制でも法的義務でもない。\nD：ダイベストメントは化石燃料等の問題企業の資産を「売却・撤退」する行動。記述はエンゲージメント（継続保有+株主として対話）の説明であり逆。\n\n【頻出】赤道原則（大規模プロジェクト融資の環境・社会リスク管理）とPRI（責任投資原則・自主的）の区分は頻出。\n【混同注意】ダイベストメント（売却・撤退）とエンゲージメント（保有継続+対話による変革）は投資家の気候変動対応として対照的なアプローチ。"
