"explanation": "ア・イ・エが正しい。ウが誤り。\n\nア：正しい。産業エコロジーは自然生態系の物質循環・エネルギーフローを産業システムに応用し、廃棄物ゼロ化・資源効率最大化を目指す学問・手法。\nイ：正しい。デンマークのカルンボーでは発電所・製油所・石膏ボード工場・薬品会社等の企業が廃熱・廃ガス・廃水等を相互利用するエコインダストリアルパークの原型として1970年代から発展し、世界の産業共生の代表事例とされる。\nウ：誤り。産業共生は競合・非競合を問わず、異業種間（発電所と農場、製油所と建材工場等）での副産物・廃棄物の相互活用が典型例であり、競合企業間に限定されない。\nエ：正しい。MFA（Material Flow Analysis）は国家・地域・企業レベルで物質の投入・産出・蓄積量を定量化する手法。日本の資源生産性・循環利用率の算定にも活用されている。\n\n【頻出】カルンボー・エコパーク（産業共生の世界的先進事例）とMFAの概念は頻出。\n【混同注意】産業共生（Industrial Symbiosis）はEIP（エコ・インダストリアル・パーク）の中核概念であり、企業間の競争関係ではなく「補完・協力」を重視する点が特徴。"
