"explanation": "光化学オキシダントはNOₓとVOC（揮発性有機化合物）が太陽の紫外線を受けて光化学反応を起こすことで生成されるオゾン（O₃）等の酸化性物質の総称。夏季の日中に濃度が上昇し光化学スモッグを引き起こす。目・のどへの刺激・農作物被害が主な影響。\n\nB：光化学オキシダントはSOₓではなくVOCとNOₓの光化学反応で生成される。降水中の酸性成分の主原因はSOₓ・NOₓが雨水に溶けることによる酸性雨であり、別の現象。\nC：PM2.5の環境基準値（日本）は年間平均15μg/m³以下・日平均35μg/m³以下（微細粒子状物質の環境基準）。数値が誤り。また粒径は2.5mm（ミリ）ではなく2.5μm（マイクロメートル）以下。\nD：COは不完全燃焼（自動車エンジン・暖房器具等）により発生し、自動車排ガスが主要発生源の一つ。SOₓとは無関係。\n\n【頻出】光化学オキシダントの生成メカニズム（NOₓ+VOC+紫外線）と、PM2.5の環境基準値・粒径の単位（μm）は頻出。\n【混同注意】光化学スモッグ（夏季・光化学オキシダント）と冬季スモッグ（SOₓ・ばいじん等）は季節・原因物質・生成機序が異なる。"
