"answer": 0,
"explanation": "BOD（Biochemical Oxygen Demand）は河川水中の有機物が好気性微生物によって分解される際に消費される酸素量（mg/L）を示す。有機汚染が進むほどBODは高く、清浄な河川では1mg/L程度、重度汚染では10mg/L以上になる。日本の河川の環境基準にBODが使用される。\n\nB：COD（Chemical Oxygen Demand）は化学的酸化剤（過マンガン酸カリウム等）で水中有機物を酸化する際の酸素消費量であり、溶存酸素量そのものを測定するものではない。CODも有機汚染の指標であり、高いほど汚染が進んでいる。湖沼・海域の環境基準に使用。\nC：DO（Dissolved Oxygen、溶存酸素量）は有機物濃度ではなく水中の酸素濃度を示す。DO値が低いほど酸素が少なく（有機物分解による酸素消費等）水質が悪化しているサインであり、魚類生存に影響する。\nD：日本の環境基準では河川にBOD・湖沼と海域にCODが適用される（逆ではない）。\n\n【頻出】BOD（河川・有機物指標）・COD（湖沼・海域・有機物指標）・DO（溶存酸素・高いほど良好）の3指標の定義と使用水域の区分は頻出。\n【混同注意】BODとCODは共に有機汚染の指標だが、測定方法（生物的vs化学的）と適用水域（河川vs湖沼・海域）が異なる。"
