"explanation": "設備利用率15%・1kWのパネルの年間発電量＝1kW×8,760時間（1年）×0.15＝1,314kWh≒1,315kWh。この計算式は太陽光発電の年間発電量の概算に使用される基本公式。\n\nA：設備利用率の定義は正しいが、数値の記述として最も正確なのはDの計算結果を確認するAよりもDが正答。なお太陽光は概ね12〜18%、陸上風力は20〜30%という記述自体は概ね正しいが、Dが具体的な計算結果として完結しており正確。\nB：太陽光発電の設備利用率は日照時間の制約（夜間・曇天等）により15%前後が一般的であり、80%以上は不可能。原子力発電が70〜90%程度で最高水準。\nC：kWh（キロワット時）はエネルギー量（電力量・積算値）の単位。「出力」（瞬間の電力）はkW（キロワット）。kWhとkWの混同は最多ミスの一つ。\n\n【頻出】設備利用率の概念と計算方法（kW×時間×利用率＝kWh）・kWとkWhの違いは頻出の基礎計算。\n【混同注意】kW（出力・能力）とkWh（電力量・エネルギー）の単位の違いを確実に区別すること。"
