"answer": 0,
"explanation": "石油換算トン（toe：tonne of oil equivalent）はIEAが使用するエネルギー比較の国際単位。石油1トンの標準的な発熱量（約41.87GJ＝約11,630kWh）を基準として各種エネルギー源を換算・比較する。1Mtoe（メガ石油換算トン）＝100万toe。\n\nB：kcalとkWhは換算可能。1kWh＝860kcal（1kcal＝4.186J、1kWh＝3,600kJ＝860kcalの関係）。「換算不可」は誤り。\nC：SI接頭辞：ギガ（G）=10⁹、テラ（T）=10¹²、メガ（M）=10⁶の関係。1TW＝10⁶MW（100万MW）＝10⁶MWであり、100MWは誤り。T＝Mの100万倍（10⁶倍）。\nD：ピーク電力は需要が集中する夏季昼間・冬季夕方等の最大電力需要時の電力（kW）を指す。年間平均ではなく最大需要時の概念。\n\n【頻出】toeの定義（1toe≒41.87GJ）とSI接頭辞（M=10⁶・G=10⁹・T=10¹²）の関係は計算問題として頻出。\n【混同注意】kW（出力・瞬間値）とkWh（電力量・積算値）の区別に加え、MW・GW・TW等の接頭辞の大小関係を確実に整理すること。"
