"answer": 0,
"explanation": "GWP（Global Warming Potential）はCO₂＝1を基準として各温室効果ガスの100年間での温暖化影響力を比較する指標（IPCC AR5・AR6の値）。CH₄のGWP100は約27〜28（AR6）、N₂OのGWP100は約273（AR6）、HFC-134aは約1,530、SF₆は約23,500。\n\nB：CO₂のGWPは「1」（基準値）であり「0」ではない。GWPが負の値を示すガスは通常の温室効果ガスにはない。\nC：CH₄のGWPはCO₂の約27〜28倍であり、同一ではない。メタン1tのCO₂換算は約27〜28tCO₂eq。\nD：GWPは評価期間によって異なる。CH₄のGWP20（20年）は約82、GWP100（100年）は約28程度と大きく異なる。短寿命ガス（CH₄等）は短期評価でより高い値を示す。\n\n【頻出】主要ガスのGWP数値（CH₄≒27・N₂O≒273・SF₆≒23,500）と、GWPが評価期間依存という特性は頻出。\n【混同注意】AR4値（CH₄＝25・N₂O＝298）とAR5・AR6値（CH₄＝28・N₂O＝273）は改訂されており、最新版の数値に注意。試験では概数で理解すれば十分。"
