"explanation": "資源生産性（Resource Productivity）はGDP÷天然資源等投入量（TMR又は国内物質消費量DMC等）で算出され、単位資源量あたりのGDPを示す指標。値が高いほど資源を効率的に経済活動に活かしている。日本は資源生産性が比較的高い水準にある。\n\nB：定義が誤り。資源生産性はGDP÷資源投入量であり、採掘量÷人口（一人あたり採掘量）ではない。\nC：日本の循環利用率（リサイクル素材の総投入量に占める割合）は約15〜18%程度で、ヨーロッパ諸国と概ね同水準であり「世界最低」は誤り。\nD：隠れたフロー（Hidden Flow）はMFAの概念で、採掘・収穫された資源に伴って移動するが経済的に利用されない物質（土砂・廃石・収穫残渣等）を指す。不法取引とは無関係。\n\n【頻出】資源生産性の定義（GDP÷資源投入量）と循環利用率は資源循環政策の基本指標として頻出。\n【混同注意】DMC（国内物質消費量）・TMR（総資源必要量）・MFA（物質フロー分析）はいずれも資源循環の定量評価に使われる異なる指標・手法。"
