"explanation": "IPCC AR6（WG1・WG2）の予測では、SSP1-2.6（低排出）シナリオで2100年の海面上昇中央値約0.32〜0.62m、SSP5-8.5（高排出）シナリオで約0.63〜1.01mが中央値。ただし氷床不安定性の不確実性から高排出シナリオで2m超のテールリスクも否定できないとされている。\n\nB：1cm以内という数値は現在の実測値ですら年間3〜4mm（1年あたり）であり、2100年までの累積で1cm以内というのは明らかに誤り。\nC：海面上昇の原因は①海水の熱膨張と②陸上氷河・氷床（グリーンランド・南極）の融解の両方が寄与。現在は氷の融解の寄与が増大傾向。\nD：現在の海面上昇速度は約3.3〜4mm/年であり、20世紀前半の年間約1.4mmより加速していることが衛星観測で確認されている。\n\n【頻出】IPCC AR6の海面上昇予測値（低排出0.3〜0.6m・高排出0.6〜1.0m）と原因（熱膨張＋氷の融解）は頻出。\n【混同注意】海面上昇は「熱膨張」と「氷床融解」の両方が原因。どちらか一方のみというのは誤り。"
