"explanation": "エコロジカルフットプリント（EF）はマティース・ワッカーネーゲルとウィリアム・リースが1990年代に開発。食料・住居・エネルギー・交通等の消費を支えるのに必要な生産可能な土地・海洋面積（グローバルヘクタール：gha）で示す。現在の世界の総EFは地球のバイオキャパシティの約1.75倍（地球約1.75個分が必要）とされており、超過分を「アース・オーバーシュート」と呼ぶ。\n\nB：企業の踏み荒らし面積記録という説明は誤り。個人・国・世界全体の消費が必要とする生産可能面積を換算する指標。\nC：現在はバイオキャパシティの1.7〜1.8倍程度のフットプリントが確認されており、「50%未満・余裕あり」は正反対の誤り。\nD：個人のライフスタイル（食事・移動・エネルギー等）によるEFの計算・比較ツールとして個人向け啓発にも活用されている（オンライン計算機等）。\n\n【頻出】エコロジカルフットプリントの定義（必要な生産可能面積）と現在の超過状況（地球約1.7個分）は頻出。\n【混同注意】エコロジカルフットプリント（消費の土地面積換算）とカーボンフットプリント（CO₂排出量換算）は異なる指標。EFはCO₂吸収に必要な森林面積も含む広い概念。"
