"answer": 0,
"explanation": "環境容量（Environmental Capacity）は生態系・環境が自浄作用（物理的・化学的・生物的分解・吸収）によって汚染を無害化できる限界量。この限界を超えると環境への蓄積・悪化が生じる。河川のBOD負荷に対する自浄能力、大気のCO₂吸収能力、土壌の重金属蓄積限界等に適用される概念。\n\nB：キャリングキャパシティ（環境収容力）は生態学では特定環境が持続的に支えられる最大個体数を指すが、人間社会にも地球の人口支持力・資源・エネルギーの観点で適用され議論されている。「人間には適用できない」は誤り。\nC：環境負荷は環境に対する「マイナスの影響・ストレス」を意味する用語。「有益な影響」「プラス」という説明は完全に逆。\nD：自然の自浄・吸収能力は有限であり、CO₂・プラスチック・重金属等の過剰投入は環境の許容範囲を超え蓄積・悪化する。「無限大・完全処理」は誤り。\n\n【頻出】環境容量（自浄能力の限界）・環境負荷（マイナスの影響）・キャリングキャパシティ（収容能力の上限）の3用語の正確な定義は環境科学の基本用語として頻出。\n【混同注意】「環境負荷が大きい」＝「環境へのマイナス影響が大きい」という意味であり、「プラスの負荷」という表現は誤用。"
