"explanation": "ケニア出身の環境活動家ワンガリ・マータイは2004年にノーベル平和賞を受賞（アフリカでの植林運動「グリーンベルト運動」の功績）。2005年に来日した際、日本語の「もったいない」（無駄にしない・大切にする精神）に感銘を受け、Reduce・Reuse・Recycle（3R）にRespect（尊重）を加えた「もったいない＝4R」として世界に発信した。\n\nB：「もったいない」は日本語特有の概念であり、1970年代から英語圏で使われてきた表現ではない。国際語「Mottainai」として広まったのはマータイの活動以降。\nC：ワンガリ・マータイはノーベル平和賞（2004年）受賞者であり、工業化推進ではなくグリーンベルト運動（植林・環境・女性の権利）での貢献が評価された。\nD：「もったいない」の精神は文化的概念であり、廃棄物処理法の法的条文に明記されているわけではない。\n\n【頻出】ワンガリ・マータイの「もったいない＝4R」発信と、ノーベル平和賞・グリーンベルト運動の関連は頻出。\n【混同注意】「もったいない」は3Rに「Respect」を加えた4Rとして紹介されたが、法律上の3Rの優先順位（リデュース＞リユース＞リサイクル）とは独立した概念。"
