"explanation": "日本初の国立公園は1934年3月に指定された瀬戸内海・雲仙（長崎）・霧島（鹿児島・宮崎）の3か所。その後、阿蘇（1934年12月）・日光・中部山岳・阿寒・大雪山等が続いた。現在は34か所（2024年時点）が指定されている。根拠法は現在の自然公園法（1957年制定）。\n\nB：日本の国立公園制度は1931年の旧国立公園法制定・1934年の初指定であり、1972年以前から存在する。\nC：日本の国立公園は米国型（完全国有地）と異なり、私有地・農地・集落を含む「地域制」の保護方式を採用している。これが日本の国立公園の特徴の一つ。\nD：国立公園の指定・管理は国（環境大臣）が行い、都道府県は国定公園を管理する。役割が逆。\n\n【頻出】日本初の国立公園（1934年・瀬戸内海・雲仙・霧島）と地域制保護方式（私有地含む）は頻出。\n【混同注意】国立公園（国管理）・国定公園（都道府県管理）・都道府県立自然公園（都道府県指定・管理）の3区分を確実に整理すること。"
