"answer": 0,
"explanation": "持続可能な開発委員会（CSD）は1992年リオ地球サミット後に設置され、アジェンダ21の実施状況のフォローアップを担った。2012年のリオ+20でCSDを廃止し、より政治的な権威を持つHLPF（High-level Political Forum on Sustainable Development）を国連総会・経済社会理事会の下に設置することが決定。HLPFは2016年から毎年開催（閣僚級）され、SDGsの進捗・VNR（自発的国家レビュー）の発表の場となっている。\n\nB：CSDはIPCCとは全く別の機関。IPCCは科学的評価専門であり、CSD/HLPFは政府間の政策フォローアップ機関。\nC：HLPFは国連総会・経済社会理事会（ECOSOC）の下に置かれた機関であり、WTOとは無関係。\nD：CSDは2013年にHLPFへの移行に伴い廃止されており、現在は存在しない。\n\n【頻出】CSD（1992年設置→2013年廃止）とHLPF（2013年設置・SDGs進捗フォローアップ）の変遷はリオ+20の成果として頻出。\n【混同注意】HLPFはSDGs（2030アジェンダ）のフォローアップ機関であり、UNFCCCの機関（COPやSBSTA）とは異なる枠組み。"
