"explanation": "地球温暖化対策計画は温対法第8条に基づき政府が策定。2021年10月に改定された現行計画では2030年度46%削減（2013年度比）・50%の高みへの挑戦・2050年カーボンニュートラルを目標として明記。電源構成（エネルギーミックス）・産業・運輸・民生・農業・吸収源各分野の対策も規定している。\n\nB：温対法第8条に基づく政府の法定計画であり、閣議決定される公式文書。民間の自主計画ではない。\nC：再エネ（太陽光・風力・水力・地熱・バイオマス）の大幅拡大が計画の中核であり、「再エネ禁止」は明らかに誤り。\nD：計画の法的拘束力は各省庁・地方公共団体に対する取り組み義務等を含むが、個別の罰則よりも「進捗管理・見直し」のメカニズムが基本。「拘束力ゼロ」は誤り。\n\n【頻出】地球温暖化対策計画（温対法根拠・2021年改定・46%削減目標）は日本の気候政策の最重要文書として頻出。\n【混同注意】地球温暖化対策計画（GHG削減の包括計画）とエネルギー基本計画（電源構成・エネルギーミックス）は別文書だが連動して策定される。"
