"explanation": "生態系の物質循環では生産者（光合成生物）が無機物を有機物に変換し、消費者（草食・肉食動物）を経て、分解者（細菌・菌類）が有機物を無機物に戻すことで物質が循環する。エネルギーは太陽光から生態系に流入するが、各栄養段階（トロフィックレベル）で約10%（生態学的効率）のみが次段階に伝達され、残りは熱として散逸する。\n\nB：エネルギー転換効率は通常10%前後（生態学的効率の法則）であり、100%ではない。これにより高次消費者ほど個体数・生体量が少なくなる（エネルギーピラミッド）。\nC：分解者が生成した無機物（窒素・リン・ミネラル等）は土壌・水中に戻り、生産者（植物）に再吸収される（栄養塩の循環）。外部排出されるわけではない。\nD：現実の生態系では一種の生物が複数の餌を食べ、複数の捕食者に食べられる複雑な食物網（フードウェブ）を形成している。単一直線連鎖は単純化したモデル。\n\n【頻出】生態学的効率（約10%）とエネルギーピラミッドの概念・分解者の物質循環における役割は頻出。\n【混同注意】食物連鎖（単純な直線モデル）と食物網（フードウェブ、現実の複雑なネットワーク）の区別を整理すること。"
