"explanation": "生物濃縮（Bioaccumulation・Biomagnification）は脂溶性・難分解性・残留性の物質が食物連鎖を通じて上位の消費者ほど高濃度に体内蓄積される現象。DDT・PCB・有機水銀（メチル水銀）・ダイオキシン類等が典型例。魚類・鳥類・哺乳類・人間（頂点捕食者）で最も高い濃縮率を示す。水俣病（メチル水銀）やDDTによる猛禽類（ハクトウワシ等）の繁殖障害が代表的事例。\n\nB：生物濃縮は水に溶けにくく（脂溶性が高く）分解されにくい物質で起きやすい。易分解性・水溶性の物質は体内に蓄積されにくい。記述が逆。\nC：生物濃縮は食物連鎖全体を通じて起こり、高次消費者ほど濃縮係数が高くなる。植物段階のみではない。\nD：DDT・PCBはストックホルム条約（POPs条約）で廃絶・禁止対象とされており、広く使用されている現状はない。使用増加の政策は環境政策と逆方向。\n\n【頻出】生物濃縮の定義（脂溶性・難分解性・食物連鎖を通じた濃縮）と代表物質（DDT・PCB・有機水銀）は頻出。\n【混同注意】生物濃縮（Biomagnification、食物連鎖を通じた濃縮増幅）と生物蓄積（Bioaccumulation、個体内での蓄積）は厳密には異なるが、エコ検定では同義的に扱われることが多い。"
