"explanation": "ミレニアム生態系評価（MA）の4分類のうち、調整サービス（Regulating Services）は生態系プロセスによる環境条件の調節機能を指す。具体例：気候調節（炭素吸収・蒸散冷却）・洪水・侵食・なだれ・病害虫の調節・水質・空気の浄化・授粉（花粉媒介）・疾病・害虫コントロール等。\n\nB：食料・木材・淡水・医薬品原料等の有形産出物は「供給サービス（Provisioning Services）」に含まれる。\nC：景観美・精神的・宗教的意義・レクリエーション・教育的価値は「文化的サービス（Cultural Services）」に含まれる。\nD：土壌形成・光合成・栄養循環等の他サービスの基盤となる機能は「基盤サービス（Supporting Services）」に含まれる。\n\n【頻出】MA（ミレニアム生態系評価）の4分類（供給・調整・文化・基盤）と各分類の具体例の対応は最重要テーマ。特に調整サービスと供給サービスの混同が最多ミス。\n【混同注意】授粉（花粉媒介）は「調整サービス」に含まれる点に注意。農産物の収穫（供給）を可能にする前提機能として位置付けられる。"
