"answer": 0,
"explanation": "サンゴ（刺胞動物）は体内に共生する褐虫藻（光合成藻類）から光合成産物の供給を受けている。海水温上昇・酸性化・強い紫外線等のストレスで褐虫藻が排出されると白化が起きる。短期間で水温が回復すれば褐虫藻が戻り回復するが、長期化するとサンゴは死滅。2016年・2020年・2024年の大規模白化（グレートバリアリーフ等）が報告されている。\n\nB：造礁サンゴは熱帯・亜熱帯の水温25〜29℃・透明度の高い浅海（200m以浅）に分布する。深海型（冷水性）サンゴも存在するが代表的なサンゴ礁は熱帯浅海。\nC：白化は主に海水温の上昇（+1〜2℃以上が数週間継続）・海洋酸性化（炭酸カルシウムの骨格形成阻害）・強紫外線等が原因。「温暖化・酸性化が影響しない」は誤り。\nD：サンゴは動物（刺胞動物門）であり植物ではない。褐虫藻という植物プランクトンを「共生」させてエネルギーを得るが、サンゴ自体は動物。\n\n【頻出】サンゴ白化のメカニズム（褐虫藻の離脱）と原因（海水温上昇・酸性化）はセットで頻出。\n【混同注意】サンゴ（動物）・褐虫藻（植物プランクトン・共生藻）・サンゴ礁（生態系）の3者を整理すること。"
