"answer": 0,
"explanation": "生物多様性ホットスポットはノーマン・マイアーズが1988年に提唱し、コンサベーション・インターナショナルが定義を精緻化。指定基準は①固有種が維持管束植物1,500種以上②元の植生の70%以上が消失している（深刻な脅威）の両方を満たす地域。現在36地域が指定。ただし原生熱帯雨林（アマゾン全体等）は植生消失が進んでいない部分はホットスポット外となる場合もある。\n\nB：ホットスポットは固有種が「多く・危機的」な地域であり、保護優先度が「最も高い」地域。記述が逆。\nC：地中海性気候域（地中海・カリフォルニア・ケープフローラル・南西豪等）や島嶼（マダガスカル・フィリピン等）もホットスポット指定を受けている。熱帯雨林限定ではない。\nD：指定基準は降水量ではなく、固有種数（維持管束植物1,500種以上）と生息地消失率（70%以上）の2要件。\n\n【頻出】生物多様性ホットスポットの定義（固有種多数＋生息地消失深刻）と提唱者（マイアーズ）・管理機関（コンサベーション・インターナショナル）は頻出。\n【混同注意】ホットスポット（固有種集中＋危機的地域、保護最優先）とウォームスポット（将来の気候変動で生息地がずれる地域）は異なる概念。"
