"answer": 0,
"explanation": "ESD（Education for Sustainable Development）はUNESCOが主導する教育アプローチ。2005〜2014年の「国連ESDの10年」から発展し、2015〜2019年は「ESDに関するグローバル・アクション・プログラム（GAP）」、2020〜2030年は「ESD for 2030」として継続。環境・経済・社会の三側面を統合的に扱い、批判的思考・協働・システム思考・将来志向の能力育成を重視。日本はユネスコスクールを通じて推進。\n\nB：ESDは自然科学に限定されず、社会科・道徳・総合学習・芸術・体育等のあらゆる教科・活動を通じた横断的アプローチが特徴。\nC：10年計画終了後もGAP・ESD for 2030として国際的推進が継続しており「廃止」は誤り。日本もユネスコスクールを中心に取り組みが続いている。\nD：ESDの対象は環境のみでなく、貧困・人権・ジェンダー・文化多様性・平和・民主主義・健康等の幅広い社会課題をカバーする。\n\n【頻出】ESDの定義（持続可能な担い手育成・統合的・横断的）と国連ESDの10年（2005〜2014年）→GAP→ESD for 2030の経緯は頻出。\n【混同注意】ESD（持続可能な開発のための教育）と環境教育（環境問題に特化した教育）は関連するが、ESDはより広い社会課題を包含する上位概念。"
