"answer": 0,
"explanation": "環境正義（Environmental Justice）は1980〜90年代に米国の有色人種・低所得者コミュニティ周辺に廃棄物処分場・有害施設が集中して立地されているという問題を起点に発展した社会運動・概念。「環境人種差別」「環境不公正」と呼ばれる不均等な環境リスク分配の是正と、意思決定への公正な参加を求める。SDGsの「誰一人取り残さない」原則とも深く関連。\n\nB：環境正義は自然の権利（Rights of Nature）とは異なり、人間社会の公正・平等を中心に据えた社会正義の概念。\nC：環境リスクの不公平な分配は先進国・途上国を問わず、貧困・マイノリティ・先住民族への集中として世界各地で観察されている。\nD：環境正義の実現は経済成長の全面停止を必要条件としない。公正で包括的な政策立案・規制の厳格化・コミュニティへの参加保障等で達成を目指す。\n\n【頻出】環境正義の起源（米国・有色人種コミュニティへの有害施設集中）と定義（環境リスクの公平な分配・意思決定への参加）は頻出。\n【混同注意】環境正義（人間社会の公正・分配問題）と気候正義（気候変動の影響と責任の公正性）は重なる部分があるが異なる文脈で発展した概念。"
