"explanation": "オーフス条約（1998年・ECE（国連欧州経済委員会）採択）は①環境情報へのアクセス、②環境に関する意思決定への市民参加、③環境問題に関する司法へのアクセスの3本柱を規定した国際条約。EU加盟国・一部非EU諸国が締約。日本は未批准だが、条約の理念は日本の情報公開法・パブリックコメント制度・環境アセスメント等に反映されている。\n\nB：環境政策への市民参加は多くの国で制度的に保障されており（環境アセスメントの意見書・パブリックコメント等）、「禁止」は事実と逆。\nC：パブリックコメント制度（行政手続法）では提出された意見を行政が考慮することが求められ、単に「無視してよい」という規定はない。ただし採択を義務付けるものではなく、考慮・回答公表が義務付けられる。\nD：NGO・NPO等の市民社会組織はCOP・CBD等の国際交渉でもオブザーバーとして参加が認められており、環境政策への市民社会の貢献は国際的に重要視されている。\n\n【頻出】オーフス条約の3本柱（情報・参加・司法）と日本の環境アセスメント・パブリックコメントとの関係は頻出。\n【混同注意】パブリックコメントは「意見を考慮する義務」はあるが「採択する義務」はない点（考慮義務vs採択義務）を区別すること。"
