"explanation": "コモンズの悲劇（Tragedy of the Commons）はハーディン（1968年）が提唱。放牧地・漁場等の共有資源では各個人が自己利益を追求すると過剰利用で資源が枯渇する問題。エリノア・オストロム（2009年ノーベル経済学賞）は世界各地の事例研究から、コミュニティが適切なルール・制度（明確な境界・監視・制裁・参加型意思決定等）を構築すれば私有化・国有化なしに持続可能な管理が可能と実証した。\n\nB：オストロムの研究がコモンズの持続可能な管理の可能性を実証しており、「必ず起きる・不可避」は誤り。\nC：オストロムは私有化・国有化ではなく「コミュニティによる自治的管理（ポリセントリックガバナンス）」の有効性を主張した。私有化か国有化かの二択を否定した点が重要。\nD：コモンズの概念は大気（温暖化問題）・海洋（公海の漁業資源）・デジタルコモンズ（オープンソース・知識）等グローバルな共有財にも広く適用されている。\n\n【頻出】コモンズの悲劇（ハーディン）とオストロムの反論（コミュニティ自治管理）の対比は頻出のクラシック問題。\n【混同注意】オストロムの主張は「私有化も国有化も必須でない」という第3の道（コミュニティガバナンス）であり、ハーディンの「私有化か国有化か」という二択への反論である点が核心。"
