"explanation": "マルチステークホルダープロセス（MSP）は環境・社会課題の解決において政府・企業・NGO/NPO・学術機関・地域コミュニティ・先住民族・消費者等の多様な関係者が包括的に参加し、対話・協議・協働することで政策・基準・解決策を共同形成する手法。国連CSD・GRI・FSC（森林認証）・MSC等の多くの国際基準がMSPで策定されてきた。\n\nB：ステークホルダーは株主のみでなく、企業活動に利害関係を持つすべての関係者（従業員・顧客・地域住民・NGO・将来世代等）を指す。株主のみへの限定は「シェアホルダー」の概念。\nC：NGOは環境政策の形成・実施・モニタリングにおいて政府・企業とのパートナーシップを組む場合も多く、「常に反対勢力」は一面的で誤り。\nD：ステークホルダーエンゲージメントはISO26000・GRIスタンダード・TCFDでも重要な経営原則として位置付けられており、環境・社会課題の解決に直結する経営プロセス。\n\n【頻出】マルチステークホルダープロセスの定義（多様な関係者の包括的参加・協働）と環境標準・政策形成への活用は頻出。\n【混同注意】ステークホルダー（利害関係者全体）とシェアホルダー（株主）は異なる概念。ステークホルダー資本主義はシェアホルダー資本主義（株主至上主義）に対する概念。"
