"explanation": "世界遺産条約（Convention Concerning the Protection of the World Cultural and Natural Heritage、1972年採択）は文化遺産・自然遺産・複合遺産の3種類を対象とし、「顕著な普遍的価値（OUV）」を持つ遺産を世界遺産一覧に記載して保護・保全を推進する。2024年時点で195か国・1,200か所以上が登録。日本の世界遺産（知床・白神山地・屋久島・小笠原等が自然遺産、富士山・法隆寺等が文化遺産）。\n\nB：世界遺産条約は文化遺産・自然遺産の両方を対象。別々の条約ではなく一つの条約で統合的に保護する点が特徴。\nC：世界遺産の自然地域でも持続可能な観光（エコツーリズム）・一般来訪が認められているものが多い。「完全禁止」は誤り。ただし登録後も適切な保全管理が求められる。\nD：複合遺産は自然遺産と文化遺産の両方の価値を持つ遺産として世界遺産条約で認められており、現在数十か所が複合遺産として登録されている（例：トンガリロ国立公園・マチュピチュ等）。\n\n【頻出】世界遺産条約（1972年・ユネスコ）の3分類（文化・自然・複合）と「顕著な普遍的価値（OUV）」の概念は頻出。\n【混同注意】世界遺産条約（文化・自然の統合保護）とラムサール条約（湿地）・CITES（取引規制）等の他の自然環境条約の対象・目的を混同しないこと。"
