"explanation": "ソルアスタルジア（Solastalgia）はオーストラリアの哲学者グレン・アルブレクトが2003年頃に提唱した概念。「故郷（solacium）」と「痛み（algia）」を組み合わせた造語で、炭鉱開発・洪水・干ばつ・山火事・海岸浸食等による自分の居住地・故郷の環境変化・喪失から生じる心理的苦痛・不安・悲嘆を指す。気候変動の精神的健康影響として近年注目されている。\n\nB：ソルアスタルジアは農村移住への憧れではなく、居住地の環境が変化・悪化することへの心理的苦痛。移住願望とは異なる概念。\nC：環境心理学は人間の行動・態度・価値観と環境問題の関係を研究し、環境配慮行動の促進・政策設計への応用等に貢献している。「全く貢献しない」は誤り。\nD：ソルアスタルジアは農村・沿岸・先住民族コミュニティ（土地・自然との結びつきが特に強いコミュニティ）で特に顕著に発生するとされており、富裕層限定の概念ではない。\n\n【頻出】ソルアスタルジアの定義（環境変化による心理的苦痛）と提唱者（アルブレクト）は近年急速に注目度が上がっている時事的概念として頻出。\n【混同注意】ソルアスタルジア（居住地の環境変化による苦痛）とノスタルジア（過去への郷愁）は語源は似るが全く異なる概念。"
