"answer": 0,
"explanation": "V2G（Vehicle to Grid）はEV車載電池の余剰電力を双方向充電器（bi-directional charger）を通じて電力系統へ放電する技術。EVを分散型の移動式蓄電池として活用し、再エネ余剰時に充電・需給逼迫時に放電することで系統調整力として機能させる。V2H（Vehicle to Home）は系統ではなく家庭内への給電技術。日本でも日産リーフ等でV2H対応が普及している。\n\nB：V2Gはグリッドへの「放電」を含む双方向技術がポイントであり、充電のみの「一方向」ではない。充電のみはV1G（単方向スマート充電）と呼ぶ場合がある。\nC：EVは充電時に需要増をもたらすが、スマート充電・V2Gを通じて充電時間帯の制御・再エネ余剰の活用・系統調整力の提供が可能。「系統安定化に貢献できない」は誤り。\nD：V2H（Vehicle to Home）はEVから家庭内電力を供給する技術。「高圧送電」「別系統充電」という説明は誤り。\n\n【頻出】V2G（系統への放電）とV2H（家庭への給電）の違い・EVの分散型蓄電リソースとしての活用は頻出テーマ。\n【混同注意】V2G（Vehicle to Grid）・V2H（Vehicle to Home）・V2B（Vehicle to Building）・V2L（Vehicle to Load）の用語を整理すること。"
