"answer": 0,
"explanation": "グリッドパリティ（Grid Parity）は再エネ発電コスト（LCOE）が系統電力の小売価格と等しくなるコスト水準。これを超えると補助金なしでも競争力を持つ。太陽光発電は世界的にグリッドパリティを達成しつつあり（IEA・IRENA）、日本でも大規模太陽光・住宅太陽光でほぼパリティに達してきた。さらに再エネが既存電源より安くなる「発電所パリティ」の概念もある。\n\nB：グリッドパリティはエネルギーコストの経済的指標であり、電圧均一性とは無関係。\nC：グリッドパリティ達成後も系統連系費用・土地制約・出力変動対策コスト等の課題があり、「無条件に採算」「追加支援不要」は一般化できない。\nD：日本の大規模太陽光・住宅太陽光はFIT単価の大幅低下が進み、グリッドパリティに近づいているとされている（電力価格の上昇も影響）。「全く達していない」は現状認識として誤り。\n\n【頻出】グリッドパリティの定義（再エネLCOE＝系統電力小売価格）とFITからの自立化への含意は頻出。\n【混同注意】LCOE（均等化発電コスト・Levelized Cost of Energy）はグリッドパリティ判断の基準となるコスト指標。設備費・燃料費・維持費・稼働率等を総合した単位電力あたりのコスト。"
