"explanation": "PCB（Polychlorinated Biphenyls）は高い絶縁性・難燃性から1954〜1972年に変圧器・コンデンサ・感圧紙等に広く使用されたが、難分解性・生物濃縮性・毒性（カネミ油症事件等）から1972年に国内製造が中止。現在も保管が続く廃PCB機器の処理を推進するため、PCB廃棄物処理特別措置法（2001年）に基づきJESCO（中間貯蔵・環境安全事業）の処理施設（全国5か所）で高温分解処理が行われており、処理期限が設定されている。\n\nB：PCBは1972年に製造禁止されており、現在の国内製造・販売はない。農薬・殺虫剤としての使用推奨は明らかに誤り。\nC：PCB廃棄物は特別管理産業廃棄物（特管廃棄物）として厳格に管理・処理される義務があり、通常の一般廃棄物収集は禁止されている。\nD：PCBは脂溶性が高く水に溶けにくい物質であり、環境中での難分解性・生物濃縮性が問題の本質。「水で希釈・無害化」は誤り。\n\n【頻出】PCBの用途（電気機器絶縁油等）・国内製造禁止（1972年）・JESCO処理・PCB廃棄物処理特措法は廃棄物行政の頻出テーマ。\n【混同注意】PCB廃棄物（特管廃棄物・JESCO処理）とアスベスト廃棄物（特管産廃・飛散防止措置）は異なる特管廃棄物の種類。"
