"explanation": "アスベスト（石綿）はクリソタイル（温石綿）・アモサイト・クロシドライト等の天然繊維鉱物。建材・断熱材・配管材として広く使用されたが、吸入による石綿肺（じん肺）・悪性中皮腫・肺がん等の深刻な疾患リスクが判明。日本では石綿含有製品の段階的規制が進み、2006年9月に原則製造・輸入・使用が全面禁止された（一部用途は2012年まで猶予）。\n\nB：2006年以降の全面禁止により、現在は使用が認められていない（極めて限定的な例外あり）。「一定基準以下は対象外」という規制緩和規定は存在しない（重量0.1%超が規制対象だが実質禁止）。\nC：アスベスト関連疾患（特に悪性中皮腫）の潜伏期間は暴露から20〜50年と非常に長く、「1〜2年・早期発見容易」は誤り。この長い潜伏期間が被害の広がりを大きくした要因の一つ。\nD：アスベスト含有廃棄物は特別管理産業廃棄物に分類され、密封・飛散防止措置・専門業者による処理が義務付けられている。通常処理は禁止。\n\n【頻出】アスベストの全面禁止（2006年）・悪性中皮腫の潜伏期間の長さ（20〜50年）・特管廃棄物としての厳格処理は頻出。\n【混同注意】アスベスト規制（2006年全面禁止）以前に建設された建物の解体時に飛散する危険があり、現在も既存建材の適切な除去・処理が課題となっている。"
