"answer": 0,
"explanation": "自然の権利（Rights of Nature）は自然（生態系・河川・山岳等）に法的人格・権利を認め、破壊された場合に人間の代理人が権利侵害を訴訟できるようにするという法的・倫理的アプローチ。エクアドルは2008年憲法改正で「自然（Pacha Mama）の権利」を世界で初めて憲法に明記。ニュージーランドのワンガヌイ川・コロンビアのアマゾン河川も法的権利を付与された事例として知られる。\n\nB：自然の権利は人間による開発・利用を促進するものではなく、自然存在の固有の権利を保護し開発による破壊から守るための概念。\nC：自然の権利は一部の国の憲法・法律・判決で認められているが、国際法上の普遍的義務としては確立されておらず、国際刑事裁判所の管轄でもない（エコサイドの犯罪化議論は別途進行中）。\nD：自然の権利は「生態中心主義」的な考え方から派生し、人間以外の存在にも固有の内在的価値を認める立場。人間中心主義とは逆の哲学的基盤。\n\n【頻出】自然の権利の概念・エクアドル憲法（2008年）が世界初の明記・ワンガヌイ川等の具体例は環境倫理の最新テーマとして頻出。\n【混同注意】自然の権利（自然存在への法的権利付与）とエコサイド（大規模な環境破壊を国際犯罪とする提唱）は関連するが異なる概念。"
