"answer": 0,
"explanation": "PPP（Polluter Pays Principle）はOECDが1972年に採用した環境政策の基本原則。汚染防止・除去・環境回復の費用を汚染者（生産者・事業者）が内部化（負担）することで、環境コストを価格に反映させる経済的手段の根拠ともなっている。廃棄物処理費用の事業者負担・土壌汚染の原因者除去義務・公害被害補償等に適用される。リオ宣言16条にも明記。\n\nB：PPPは汚染者（事業者・生産者）に費用負担を求める原則であり、被害者への転嫁は原則に反する。\nC：PPPは特定の国グループに限定されない普遍的な環境政策原則。OECDが先行採用したが、国際的なコンセンサスとして広まっている。\nD：PPPは費用負担を通じて汚染者に汚染削減インセンティブを与えるものであり、「費用を払えば汚染可能」という意味ではない。追加的な規制基準・許可制度と組み合わせて機能する。\n\n【頻出】PPPの定義（汚染者が費用負担）・OECD1972年勧告・リオ宣言16条への明記は環境法・政策の基本原則として頻出。\n【混同注意】PPP（汚染者負担）・予防原則（不確実性下での事前措置）・CBDR（差異化責任）は環境法の3大原則として並べて整理すること。"
