"answer": 0,
"explanation": "グローバル・コモンズ（Global Commons）は大気・深海底・公海・宇宙空間・南極大陸等、特定国の主権が及ばない「全人類の共有財産（Common Heritage of Mankind）」領域。気候変動（大気共有）・深海底資源（UNCLOS・ISA管理）・公海保護（高海域海洋生物多様性条約・BBNJ協定）・南極（南極条約・マドリッド議定書）の管理が課題。\n\nB：グローバル・コモンズは特定国の所有物ではなく「全人類の共有財産」概念。先進国の独占も途上国のアクセス排除も原則に反する。\nC：深海底の鉱物資源（マンガン団塊・熱水鉱床等）の採掘はUNCLOS（国連海洋法条約）に基づきISA（国際海底機構）が管理する「人類共同の財産」であり、完全な自由採掘は認められていない。\nD：南極条約（1959年採択）は南極の領土主権主張を凍結（既存の主張を認めず新規主張も禁止）し、科学的調査の自由と平和利用のみを認める。マドリッド議定書（1991年）は50年間の鉱物資源開発禁止を定めた。\n\n【頻出】グローバル・コモンズの4領域（大気・深海底・公海・宇宙）と各領域の管理枠組みは国際環境政策の頻出テーマ。\n【混同注意】BBNJ協定（2023年採択・公海保護・国家管轄外区域の海洋生物多様性条約）は最新の国際条約として近年急速に出題頻度が上がっている。"
