"適応的管理とは気候変動への「適応（Adaptation）」政策を管理・調整するための政府の官僚的プロセスを指し、生態系管理とは無関係である",
"適応的管理では最初に設定した管理計画を変更することは失敗と見なされるため、当初計画の完全実施が常に最優先とされる",
