"explanation": "環境デューデリジェンス（EDD）は企業買収・合併・不動産取得・融資前に、対象の土壌汚染（Phase I/II調査）・アスベスト・地下水汚染・廃棄物・環境法令違反・気候変動リスク等を調査・評価する手続き。汚染地取得による将来的な浄化費用負担リスクの特定・価格交渉・契約条件設定に活用。環境配慮促進法・TCFD等の開示要件強化で重要性が増している。\n\nB：EDDは「事前」（取引・投融資の決定前）に実施することが本質。事後評価では汚染リスクを織り込んだ意思決定ができない。\nC：EDDは環境問題の有無を評価するものであり、「問題なし」の証明になるとは限らない。また規制免除効果はない。\nD：環境リスク管理は規制遵守だけでなく、汚染コストの定量化・環境賠償保険・予防投資・グリーン調達等の能動的・積極的なリスク管理手法を含む総合的なアプローチ。\n\n【頻出】環境デューデリジェンス（事前の環境リスク評価）とPhase I/II調査（土壌汚染調査の段階）は不動産・M&A・投資分野での環境管理の頻出テーマ。\n【混同注意】環境デューデリジェンス（環境リスクの事前評価）とデューデリジェンス全般（財務・法務・人事等を含む企業調査）は一部として関係する。"
