"answer": 0,
"explanation": "MSY（Maximum Sustainable Yield：最大持続生産量）は魚類資源の再生産率を超えない最大漁獲量を示す概念。科学的な資源評価（資源量調査・再生産モデル）に基づきTAC（漁獲可能量）として各種・地域に設定される。FAO・日本（漁業法）・EU（共通漁業政策）等がTAC・IQ（個別割当）制度の根拠としてMSYを活用。\n\nB：MSYを超えた過剰漁獲は資源の枯渇・崩壊につながる。一度崩壊した魚類資源は回復に数十年単位を要する場合があり「自然に回復・問題なし」は誤り。太西洋のタラ・日本のマイワシ等の資源崩壊が歴史的事例。\nC：TACは科学的資源評価に基づき政府・国際機関（IOTC・WCPFC等の地域漁業管理機関）が設定・管理するものであり、漁業者の自由な自主規制ではない。\nD：IUU（Illegal, Unreported, Unregulated）漁業は科学的管理の枠外で漁獲することで資源評価の精度を下げ過剰漁獲を招く有害行為。国際的に撲滅が推進されており「推奨」は逆。\n\n【頻出】MSY・TAC・IUU漁業の定義と水産資源管理の科学的アプローチは頻出。\n【混同注意】MSY（科学的概念・最大持続生産量）とTAC（政策的ツール・漁獲可能量の設定制度）は関連するが異なる概念。"
