"explanation": "BBNJ協定（Agreement on the Conservation and Sustainable Use of Marine Biological Diversity of Areas Beyond National Jurisdiction）は2023年3月に国連で採択された歴史的な新条約。UNCLOSを実施する条約として、国家管轄外区域（公海・深海底）の海洋生物多様性について①海洋遺伝資源（MGR）のアクセスと利益配分（ABS）②公海保護区等のエリアベースの管理手段③環境影響評価（EIA）④能力構築・技術移転の4本柱を規定。「公海条約（High Seas Treaty）」とも呼ばれる。\n\nB：BBNJ協定は鉱物資源の採掘権配分ではなく、生物多様性（生物資源・生態系）の保全と利益の公平な共有を目的とする。深海底鉱物資源はISA（国際海底機構）が管理。\nC：BBNJ協定以前もUNCLOS・公海自由原則・個別の国際協定が存在したが、公海全体の生物多様性を包括的に保護する法的文書はなかった。「完全に無法」は過言だが、保護の空白が存在したことは事実。\nD：BBNJは「国家管轄外区域」（EEZ外・公海・深海底）を対象とする条約であり、EEZ内は対象外。EEZ内は沿岸国の管轄。\n\n【頻出】BBNJ協定（2023年採択・公海保護・海洋遺伝資源ABS）は国際環境法の最新かつ最重要の時事テーマとして頻出。\n【混同注意】BBNJ協定（公海・国家管轄外区域）・UNCLOS（海洋法全般）・ISA（深海底鉱物資源管理）は異なる制度として整理すること。"
