"explanation": "Climate-Smart Agriculture（CSA）はFAOが推進する概念で、①農業生産性・農家収入の向上②GHG排出削減・炭素固定（緩和）③気候変動への適応力強化の3目標を同時に追求する。農地での炭素固定（カーボンファーミング）等のクレジット創出には、信頼性確保のためのMRV（Measurement測定・Reporting報告・Verification検証）の仕組みが必須。FAO・IPCC・民間カーボン市場がMRV手法の標準化を進めている。\n\nB：農業部門のGHG（CH₄・N₂O・CO₂）は衛星・センサー・フラックス測定等で測定可能であり、完全不可能ではない。IPCC・FAOが農業排出のインベントリ手法を整備している。\nC：CSAはデジタル化・自動化だけでなく、輪作・不耕起農法・施肥最適化・水田管理・牧草地管理等によるGHG削減・適応を包含する広い概念。スマート農業（ICT活用）と混同しないこと。\nD：農業カーボンクレジットの信頼性確保にはMRV（測定・報告・検証）が不可欠。自己申告のみでは方法論の不確実性・二重計上リスクがあり、第三者検証が必要とされる。\n\n【頻出】CSA（気候スマート農業・FAO）の三目標（生産性・緩和・適応）とMRVの必要性は農業×気候変動の頻出テーマ。\n【混同注意】CSA（Climate-Smart Agriculture・三目標の統合）・リジェネラティブ農業（生態系再生型）・スマート農業（ICT活用）は異なるがオーバーラップする農業アプローチ。"
