"explanation": "SBTN（Science Based Targets for Nature）はWWF・CDP・WRI・WBCSD等が参画するScience Based Targets Networkが開発している枠組み。気候変動のSBTi（温度目標との整合的なGHG削減目標設定）の「自然版」として、企業が淡水（水消費・水質）・土地（生息地転換・劣化）・海洋・生物多様性の観点で科学的根拠に基づく目標を設定するための方法論・ガイドラインを提供。TNFDとの連動で注目が高まっている。\n\nB：SBTNは会計基準・GAAP規則ではなく、企業の自然関連目標設定のフレームワーク（科学的根拠に基づく目標設定ガイドライン）。\nC：SBTNは自主的なフレームワークであり、目標達成が法的に自然影響ゼロを保証したり訴訟免責を与えたりする効力はない。\nD：SBTNは大企業だけでなく、サプライチェーン全体・中小企業も対象として包含することを目指している。大企業限定の禁止規定はない。\n\n【頻出】SBTN（自然版SBT・気候SBTiとの対比）とTNFD・ネイチャーポジティブとの関連は企業の自然対応の最新トピックとして頻出。\n【混同注意】SBTi（Science Based Targets initiative）は気候変動（GHG削減・1.5℃目標整合）、SBTN（Science Based Targets for Nature）は自然・生物多様性が対象。気候と自然の「SBT」を区別すること。"
