"explanation": "ジャスト・トランジション・ファイナンス（Just Transition Finance）はCOP26等で議論が進んでいる金融の枠組み。石炭産業依存地域の経済多様化・再訓練・インフラ転換等を支援するための専用資金調達メカニズムとして、グリーンボンド・ソーシャルボンド・移行（トランジション）ボンド・国際的な気候資金（Green Climate Fund等）を活用する方向が模索されている。COP26の「公正な移行に関するグラスゴー宣言」等で注目。\n\nB：ジャスト・トランジション・ファイナンスは脱炭素化への移行を前提としており、化石燃料への追加投資促進は逆。移行期の社会的影響の緩和・補償が目的。\nC：途上国・石炭依存経済国（インドネシア・フィリピン・南アフリカ等）への「公正な移行」支援が主要な議論の対象であり、先進国内問題のみではない。\nD：CDM（クリーン開発メカニズム）は京都議定書の排出削減メカニズムであり、ジャスト・トランジション・ファイナンスとは全く異なる制度・概念。\n\n【頻出】ジャスト・トランジション・ファイナンスの概念（移行による影響を受ける労働者・地域・途上国への資金支援）はCOP26以降の最新テーマとして頻出。\n【混同注意】ジャスト・トランジション（移行の公正性）・ジャスト・トランジション・ファイナンス（その資金メカニズム）・気候正義（気候変動の影響の公正性）の三者の関係を整理すること。"
