"explanation": "IPCC AR6は気候変動が水循環を加速させ、湿潤地域はより湿潤に・乾燥地域はより乾燥になる傾向が強まると報告。水ストレス地域（中東・サヘル・南アジア・地中海等）での干ばつ・水不足の深刻化と、同時に極端降雨・洪水リスクの増大という複合的な影響が生じる。喜望峰型・天水農業依存地域での食料安全保障への打撃も深刻。\n\nB：降水量の増加は一部地域（高緯度・湿潤地域）で見られるが、全地域・均等増加ではない。乾燥地域では減少・蒸発増大による利用可能水量の純減が予測されており、「全地域で増加・水不足解消」は誤り。\nC：ヒマラヤ・チベット・アンデス等の氷河融解は「アジアの水の塔」への影響として深刻な問題であり、インダス・ガンジス・黄河等の大河川水源への影響が懸念されている。「アジアに及ばない」は誤り。\nD：節水・水効率化は水処理・輸送に使われるエネルギー（ポンプ・浄水）の削減を通じてGHG排出削減に貢献する面もある。また温暖化適応策でもあり、気候変動対策の一環として位置付けられる。\n\n【頻出】気候変動と水資源の複合問題（水不足悪化＋洪水リスク同時増大）・ヒマラヤ氷河融解の「ピークウォーター」問題は頻出。\n【混同注意】ピークウォーター（氷河融解による一時的な水量増加後の長期的枯渇問題）とピークオイル（石油生産量の最大後の枯渇）は異なる概念だが類似した「ピーク」の問題。"
