"explanation": "外部不経済（Negative Externality）は生産・消費活動の社会的費用が生産コストに含まれないため過剰生産・過剰消費が起きる「市場の失敗」の典型。炭素税・排出権取引・環境税等は外部不経済を「内部化（Internalization）」し、社会的費用を価格シグナルとして反映させる政策手段。ピグー税（Pigouvian Tax）はアーサー・セシル・ピグーが提唱した排出量・汚染量に応じた課税で、社会的最適水準の排出量を誘導する。\n\nB：外部不経済は市場競争上の不利益ではなく、第三者・社会への（市場を通じない）費用の転嫁を指す経済学的概念。環境汚染はその代表例。\nC：環境問題は外部不経済・公共財の特性・情報の非対称性等の「市場の失敗」により自動的に解決されず、政府の介入（規制・課税・補助金等）が正当化される。\nD：ピグー税は汚染者への補助金ではなく、排出・汚染行為に対する課税（外部不経済の内部化）。生産促進とは逆方向の政策効果を持つ。\n\n【頻出】外部不経済・市場の失敗・ピグー税（外部不経済の内部化）は環境経済学の基礎中の基礎として頻出。\n【混同注意】ピグー税（最適汚染税・外部不経済の価格化）とコースの定理（財産権の明確化による当事者間交渉で外部性を解決する理論）は外部性問題への異なるアプローチ。"
