"explanation": "食品産業のサステナビリティは複合的な課題。原材料調達：農業のGHG・水・土地使用・生物多様性影響が大きく（スコープ3上流）、持続可能認証調達が重要。LCA：製品の環境ホットスポット特定。包装：プラスチック削減・バイオマス・再生可能素材化。食品ロス：農場→製造→流通→消費者の各段階での削減（需要予測AI・フードバンク等）。スコープ3：農業（最大排出）・輸送・消費者での廃棄が主要課題。栄養・健康：プラネタリーヘルスの観点での動物性タンパク削減・植物性拡大。\n\nB：スコープ2（自社電力）の再エネ化は重要だが、食品メーカーのGHGは農業起源のスコープ3上流が最大のため、原材料・食品ロス・包装も不可欠。「電力のみで十分」は誤り。\nC：農業段階の原材料生産（スコープ3上流）と廃棄段階（スコープ3下流）の排出がサプライチェーン全体の主要な排出源。「製造段階のみ」の評価では本質を見逃す。\nD：食品ロス削減推進法（2019年）は食品メーカーを含む事業者に食品ロス削減の取り組みを求めており、「禁止」は明らかに誤り。\n\n【頻出】食品メーカーの統合的サステナビリティ（原材料認証・LCA・食品ロス・スコープ3）は食料×環境の複合実践問題として頻出。\n【混同注意】食品ロスと食品廃棄物の区別：食品ロスはまだ食べられるのに廃棄される食品（本来防止可能）、食品廃棄物はより広い概念（食べられない部分も含む廃棄全体）。"
