"explanation": "ゼロ・ウェイスト（Zero Waste）政策の実践：①リデュース優先：使い捨てプラ削減条例・過剰包装規制・食品ロス削減。②リユース推進：コンテナリターン・リペアカフェ・リユースショップ支援。③リサイクル強化：分別細分化・集団回収・食品廃棄物の堆肥化・バイオガス化。④残余廃棄物の最小化：焼却・埋立を最後の手段に。⑤多主体協働：市民・事業者・NPOとの共同取り組み・参加型計画策定。日本でも上勝町（徳島）等のゼロ・ウェイスト宣言自治体が実践例として注目されている。\n\nB：焼却施設大型化は3Rが進まなかった場合の処理策であり、ゼロウェイストの考え方とは逆。廃棄物処理業の収益よりも廃棄物発生量の削減が優先。3Rの禁止という規定は存在しない。\nC：廃棄物処理法は市町村の役割を規定するが、廃棄物削減目標の設定を禁止していない。環境基本法・循環型社会形成推進基本法に基づき独自目標設定が可能・推奨される。\nD：廃棄物処理法では市町村が分別収集の種類・方法を定めることができ、市民に適切な分別を求めることは法的に可能かつ推進されている。\n\n【頻出】ゼロ・ウェイスト政策の3R優先順位に基づく段階的実施・多主体協働・上勝町等の国内事例は廃棄物行政の実践問題として頻出。\n【混同注意】ゼロ・ウェイスト（廃棄物発生量のゼロを目指す理念）とゼロエミッション（廃棄物のリサイクル率100%・廃棄ゼロ）は類似するが微妙にニュアンスが異なる概念。"
