"explanation": "エシカル消費の実践を支援するツール群：①エコラベル：タイプⅠ（エコマーク・MSCラベル等の第三者認証）・タイプⅡ（企業の自己宣言）・タイプⅢ（EPD・LCAデータ開示）。②CFP（カーボンフットプリント）表示：製品のLCCO₂を可視化。③有機JAS・フェアトレード：農産物の持続可能性認証。④情報開示：原産地・サプライチェーン透明性・企業ESG情報へのアクセス。これらが揃うことで消費者の意思決定の質が向上し、市場を通じた持続可能な生産の促進（グリーン購買力）が期待できる。\n\nB：消費者行動研究では、エコラベル等の客観的な環境情報の表示が消費者の環境配慮行動を後押しする効果が示されており「影響しない」は誤り。\nC：エコラベルは任意の認証・表示制度であり、すべての製品への法的義務付けはない。未表示品の販売禁止規定もない（グリーン購入法はあくまで公共機関の調達基準）。\nD：CFP表示は任意の取り組みとして推進されており、法律で禁止されているわけではない（むしろ消費者庁・環境省が普及を促進）。\n\n【頻出】エコラベルの3タイプ（Ⅰ・Ⅱ・Ⅲ）とCFP表示・フェアトレード・有機JAS等のエシカル消費ツールの整理は消費×環境の実践問題として頻出。\n【混同注意】グリーン購入法（公共機関の調達義務）とエシカル消費（一般消費者の任意の購買選択）は主体・法的性格が全く異なることを区別すること。"
