"answer": 0,
"explanation": "中小企業の環境マネジメントの実践的アプローチ：①エコアクション21：環境省が策定した中小企業・学校・行政機関等向けの日本独自EMS認証制度。ISO14001より取得しやすい（費用・手順の簡略化）。②省エネ診断：省エネセンター・中小企業省エネ相談センター等の無料・低価格診断サービス。③補助金活用：省エネ設備導入・再エネ設備導入の補助金（環境省・経産省・自治体）。④グリーン調達：取引先大企業のGSCM要件への対応。⑤業界団体・商工会議所の環境支援プログラムの活用。\n\nB：中小企業は日本の事業者の99%以上を占め、合計すると環境負荷・排出量も大きい。また大企業のサプライヤーとして環境要件を求められるケースが増えており、「対策不要」は誤り。\nC：エコアクション21は中小企業が低コスト・短期間で取得できるよう設計されており、「数億円・数年」は誤り。ISO14001と比較して取得しやすさが特徴。\nD：自主的な環境目標設定・実施は環境基本法・循環型社会形成推進基本法等で企業の責務として促進されており、禁止規定はない。\n\n【頻出】エコアクション21（環境省・中小企業向けEMS）の概要とISO14001との違い（取得のしやすさ・対象規模）は頻出。\n【混同注意】ISO14001（国際規格・第三者認証・要求事項規格）とエコアクション21（日本独自・環境省策定・中小向け・認証あり）・KES（関西規格）等の国内EMS認証の違いを整理すること。"
