"answer": 0,
"explanation": "本問はエコ検定全300問の締めくくりとして、試験全体の理念を総合的に問う設問。持続可能な開発（ブルントラント定義・1987年）は環境・経済・社会の三側面の統合的達成を目指すものであり、「環境か経済か」の二項対立を超えた相互補完の視点が核心。エコ検定は環境問題の技術的知識だけでなく、経済・政策・国際関係・企業経営・個人の行動にまたがる複合的・学際的な環境リテラシーを問う検定。合格者（エコピープル）はその知識を実践・普及する担い手として社会の持続可能性向上に貢献することが期待されている。\n\nB：持続可能な開発はGDPゼロ成長の強制ではなく、質的成長・グリーン成長・デカップリング等を通じた経済発展と環境保全の統合を目指す概念。「経済成長の完全放棄」はブルントラント定義と異なる。\nC：エコ検定は法規暗記だけでなく、環境問題の背景・メカニズム・経済的視点・社会的公正・国際関係・ビジネス応用等の総合的理解を問う試験。「法規暗記のみ」は誤り。\nD：技術革新は重要だが、経済政策（炭素価格）・社会制度（ETS・再エネ法）・文化（エシカル消費）・価値観（持続可能性重視）の変革なしでは技術の社会実装は進まない。「技術のみで解決」は誤り。\n\n【頻出】環境・経済・社会の統合という持続可能な開発の三側面はエコ検定全体を貫く基本理念として最重要。バッチ10・300問目に相応しいまとめ問題。\n【混同注意】持続可能な開発の三側面（環境・経済・社会）は対立ではなく統合であり、どれか一方のみを優先する立場（環境至上主義・経済成長至上主義等）はいずれも持続可能な開発の定義と異なる。"
